        self.assertEqual(reports["r-beta-2"]["conclusion"], "duplicate")
        self.assertEqual(reports["r-beta-2"]["reason"], "duplicate")

    def test_same_outcome_different_bytes_counts_once(self):
        ops = operations()
        receipts = [
